def diff_even_odd(lst):
    even = None
    odd = None
    for i in lst:
        if i % 2 == 0 and even is None:
            even = i
        elif i % 2 != 0 and odd is None:
            odd = i
        if even is not None and odd is not None:
            break
    return even - odd

