from functools import reduce
def diff_even_odd_v6(lst):
    def find_diff(acc, num):
        even, odd = acc
        if num % 2 == 0 and even is None:
            even = num
        elif num % 2 != 0 and odd is None:
            odd = num
        return (even, odd)

    result = reduce(find_diff, lst, (None, None))
    even, odd = result
    return even - odd if even is not None and odd is not None else None

