    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5)+1, 2):
            if n % i == 0:
                return False
        return True

    # Check if a is less than 2
    if a < 2:
        return False

    # Find all prime factors of a
    prime_factors = []
    d = 2
    while d * d <= a:
        while a % d == 0:
            prime_factors.append(d)
            a //= d
        d += 1
    if a > 1:
        prime_factors.append(a)

    # Check if there are exactly 3 prime factors and they are all distinct
    if len(prime_factors) == 3 and len(set(prime_factors)) == 3:
        return True
    return False
```
