import math


def next_power_of_2(n):
    if n <= 0:
        return 1
    return 1 << (n - 1).bit_length()


def next_power_of_2_v2(n):
    if n <= 0:
        return 1
    return 2 ** math.ceil(math.log2(n))


def next_power_of_2_v3(n):
    if n <= 0:
        return 1
    if n & (n - 1) == 0:
        return n
    while n & (n - 1) != 0:
        n = n & (n - 1)
    return n << 1


