from collections import Counter

def check_occurences(lst):
    # Convert tuples to frozensets for comparison
    # This allows us to treat (a,b) and (b,a) as equivalent
    mapped = [frozenset(t) for t in lst]

    # Count occurrences using Counter
    counts = Counter(mapped)

    # Create result dictionary with original tuples as keys
    result = {}
    for key, count in counts.items():
        # Find the original tuple that corresponds to this frozenset
        for original_tuple in lst:
            if set(original_tuple) == set(key):
                result[original_tuple] = count
                break

    return result

