def dict_depth_global(d):
    if not isinstance(d, dict) or not d:
        return 0

    max_depth = [0]  # Using list to simulate global variable

    def helper(current_dict, current_depth):
        max_depth[0] = max(max_depth[0], current_depth)
        for value in current_dict.values():
            if isinstance(value, dict):
                helper(value, current_depth + 1)

    helper(d, 1)
    return max_depth[0]

