# Alternative solution using bytearray (most efficient for large strings)
def replace_spaces_v9(string):
    # Convert string to bytearray for in-place modification
    arr = bytearray(string)
    # Count spaces
    space_count = arr.count(b' ')
    # Calculate new length
    new_length = len(arr) + space_count * 2
    # Resize bytearray
    arr.extend([0] * (new_length - len(arr)))
    # Replace spaces from end to beginning
    i = len(arr) - 1
    j = len(arr) - 1
    while i >= 0:
        if arr[i] == ord(' '):
            arr[j] = ord('0')
            arr[j-1] = ord('2')
            arr[j-2] = ord('%')
            j -= 3
        else:
            arr[j] = arr[i]
            j -= 1
        i -= 1
    return arr.decode()

