def max_Abs_Diff(arr):
    if len(arr) < 2:
        return 0

    min_val = arr[0]
    max_val = arr[0]

    for num in arr[1:]:
        if num < min_val:
            min_val = num
        elif num > max_val:
            max_val = num

    return max_val - min_val

