                first_word = word
                break
        else:
            continue
        break
    for i in lst:
        words = i.split()
        for word in words:
            if word.startswith('P') or word.startswith('p') and word != first_word:
                second_word = word
                break
        else:
            continue
        break
    return (first_word, second_word)

