from collections import defaultdict

def largest_subset(nums):
    # Create a graph where an edge from a to b means b % a == 0
    # and b > a (to avoid cycles)
    graph = defaultdict(list)

    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[j] % nums[i] == 0:
                graph[nums[i]].append(nums[j])

    # Memoization dictionary to store the longest path starting from each node
    memo = {}

    def dfs(node):
        if node not in memo:
            max_length = 1  # At least the node itself
            for neighbor in graph[node]:
                max_length = max(max_length, 1 + dfs(neighbor))
            memo[node] = max_length
        return memo[node]

    # Find the maximum path length among all nodes
    max_size = 0
    for num in nums:
        max_size = max(max_size, dfs(num))

    return max_size

