def amicable_numbers_sum(limit):
    def d(n):
        """Calculate the sum of proper divisors of n."""
        divisors = []
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i and i != 1:
                    divisors.append(n // i)
        return sum(divisors)

    total_sum = 0

    # Iterate through numbers from 1 to limit - 1
    for num in range(1, limit):
        # Calculate sum of proper divisors of num
        sum_divisors = d(num)

        # Check if it's an amicable number
        if sum_divisors != num and d(sum_divisors) == num:
            total_sum += num

    return total_sum

