def count_Primes_nums(n):
    if n < 2:
        return 0
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n, i):
                is_prime[j] = False
    return sum(is_prime)

print(count_Primes_nums(5)) # Output: 2 (primes are 2 and 3)
print(count_Primes_nums(10)) # Output: 4 (primes are 2, 3, 5, 7)
print(count_Primes_nums(0)) # Output: 0
print(count_Primes_nums(1)) # Output: 0

# Alternative solution using a helper function to check for primes
def count_primes_alt(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    count = 0
    for i in range(2, n):
        if is_prime(i):
            count += 1
    return count

print(count_primes_alt(5)) # Output: 2
print(count_primes_alt(10)) # Output: 4
print(count_primes_alt(0)) # Output: 0
print(count_primes_alt(1)) # Output: 0

# Another alternative using list comprehension
def count_primes_compact(n):
    def is_prime(num):
        if num < 2:
            return False
        return all(num % i != 0 for i in range(2, int(num ** 0.5) + 1))

    return sum(1 for i in range(2, n) if is_prime(i))

print(count_primes_compact(5)) # Output: 2
print(count_primes_compact(10)) # Output: 4
print(count_primes_compact(0)) # Output: 0
print(count_primes_compact(1)) # Output: 0

# Most efficient solution using Sieve of Eratosthenes
def count_primes_efficient(n):
    if n < 2:
        return 0

    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n, i):
                sieve[j] = False

    return sum(sieve)

print(count_primes_efficient(5)) # Output: 2
print(count_primes_efficient(10)) # Output: 4
print(count_primes_efficient(0)) # Output: 0
print(count_primes_efficient(1)) # Output: 0

# Test all functions with the assertion
assert count_Primes_nums(5) == 2
assert count_primes_alt(5) == 2
assert count_primes_compact(5) == 2
assert count_primes_efficient(5) == 2

