def dict_depth(d):
    if not isinstance(d, dict) or not d:
        return 0
    return 1 + max(dict_depth(v) for v in d.values())

print(dict_depth({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using stack
def dict_depth_stack(d):
    if not isinstance(d, dict) or not d:
        return 0

    stack = [d]
    depth = 0

    while stack:
        current = stack.pop()
        if isinstance(current, dict):
            depth += 1
            for v in current.values():
                stack.append(v)

    return depth

print(dict_depth_stack({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using recursion with max depth tracking
def dict_depth_recursive(d, current_depth=1):
    if not isinstance(d, dict) or not d:
        return current_depth

    max_depth = current_depth
    for v in d.values():
        if isinstance(v, dict):
            depth = dict_depth_recursive(v, current_depth + 1)
            max_depth = max(max_depth, depth)

    return max_depth

print(dict_depth_recursive({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using a helper function to track depth
def dict_depth_helper(d):
    def helper(obj, depth):
        if not isinstance(obj, dict) or not obj:
            return depth
        return max(helper(v, depth + 1) for v in obj.values())

    return helper(d, 0)

print(dict_depth_helper({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using a generator expression
def dict_depth_generator(d):
    if not isinstance(d, dict) or not d:
        return 0
    return 1 + max(dict_depth_generator(v) for v in d.values() if isinstance(v, dict))

print(dict_depth_generator({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using collections.deque for BFS approach
from collections import deque

def dict_depth_bfs(d):
    if not isinstance(d, dict) or not d:
        return 0

    queue = deque([(d, 1)])
    max_depth = 0

    while queue:
        current_dict, depth = queue.popleft()
        max_depth = max(max_depth, depth)

        for v in current_dict.values():
            if isinstance(v, dict):
                queue.append((v, depth + 1))

    return max_depth

print(dict_depth_bfs({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using a simple iterative approach
def dict_depth_iterative(d):
    if not isinstance(d, dict) or not d:
        return 0

    depth = 1
    current_level = [d]

    while any(isinstance(item, dict) for item in current_level):
        next_level = []
        for item in current_level:
            if isinstance(item, dict):
                next_level.extend(item.values())
        current_level = next_level
        depth += 1

    return depth

print(dict_depth_iterative({'a':1, 'b': {'c': {'d': {}}}})) # 4

