def bell_Number(n):
    if n == 0:
        return 1
    elif n == 1:
        return 1
    else:
        bell = [0] * (n + 1)
        bell[0] = 1
        for i in range(1, n + 1):
            bell[i] = 0
            for j in range(i):
                bell[i] += bell[j]
        return bell[n]

