def tuple_to_dict(t):
    # Initialize an empty dictionary
    result = {}

    # Iterate through the tuple in steps of 2
    for i in range(0, len(t), 2):
        # Use adjacent elements as key-value pairs
        key = t[i]
        value = t[i + 1]
        result[key] = value

    return result

