print(is_majority([3, 3, 3, 3, 10], 5, 3))        # True
print(is_majority([1, 2, 3, 4, 5], 5, 3))         # False

print(is_majority_binary_search([1, 2, 3, 3, 3, 3, 10], 7, 3))  # True
print(is_majority_binary_search([1, 1, 2, 4, 4], 5, 4))         # False
print(is_majority_binary_search([3, 3, 3, 3, 10], 5, 3))        # True
