def count_primes_sieve_bitwise(n):
    if n < 2:
        return 0

    # Use a boolean array to track primes
    sieve = [True] * n
    sieve[0] = sieve[1] = False

    # Sieve of Eratosthenes
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n, i):
                sieve[j] = False

    return sum(sieve)

