    if n <= 0:
        return []
    elif n == 1:
        return [3]
    elif n == 2:
        return [3, 0]
    elif n == 3:
        return [3, 0, 2]

    sequence = [3, 0, 2]
    for i in range(3, n):
        next_num = sequence[i-2] + sequence[i-3]
        sequence.append(next_num)

