def diff_even_odd_v7(lst, index=0, even=None, odd=None):
    if index >= len(lst):
        return even - odd if even is not None and odd is not None else None

    if lst[index] % 2 == 0 and even is None:
        even = lst[index]
    elif lst[index] % 2 != 0 and odd is None:
        odd = lst[index]

    if even is not None and odd is not None:
        return even - odd

    return diff_even_odd_v7(lst, index + 1, even, odd)

