from collections import Counter

def check_occurences(lst):
    # Convert each tuple to a sorted tuple to handle unordered pairs
    normalized_tuples = [tuple(sorted(t)) for t in lst]

    # Count occurrences using Counter
    counts = Counter(normalized_tuples)

    # Convert back to original tuple format if needed
    result = {}
    for key, count in counts.items():
        # Find the original tuple that matches this normalized key
        for original_tuple in lst:
            if tuple(sorted(original_tuple)) == key:
                result[original_tuple] = count
                break

    return result

