import math

def sumofFactors(n):
    result = 0
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i % 2 == 0:
                result += i
            if (n // i) != i and (n // i) % 2 == 0:
                result += (n // i)
    return result + 2 if n > 1 else 0

