def extract_even(t):
    result = []
    for item in t:
        if isinstance(item, int) and item % 2 == 0:
            result.append(item)
        elif isinstance(item, tuple):
            nested_result = extract_even(item)
            if nested_result:  # Only append non-empty tuples
                result.append(nested_result)
    return tuple(result)

