print(magic_square_test([[2, 7, 6], [9, 5, 1], [4, 3, 8]]))  # Should be True
print(magic_square_test([[1, 1, 1], [1, 1, 1], [1, 1, 1]]))  # Should be True
print(magic_square_test([[1, 2], [3, 4]]))  # Should be False (not a magic square)

