from collections import Counter

def check_occurences(lst):
    # Convert tuples to frozensets for comparison
    # This allows us to treat (1, 3) and (3, 1) as equivalent
    mapped = [frozenset(t) for t in lst]

    # Count occurrences using Counter
    counts = Counter(mapped)

    # Create result dictionary with original tuples as keys
    result = {}
    for key, count in counts.items():
        # Find the first tuple that matches this frozenset
        for t in lst:
            if set(t) == set(key):
                result[t] = count
                break

    return result

