def get_total_number_of_sequences(m, n):
    # Create a 2D array to store the results of subproblems
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Base case: There's one way to form a sequence of length 0 (empty sequence)
    for i in range(m + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # For each position, we can choose any number from 1 to i
            # But it must be at least twice the previous number
            for k in range(1, i + 1):
                if k * 2 <= i:
                    dp[i][j] += dp[k][j - 1]

    return dp[m][n]

# Test the function
print(get_total_number_of_sequences(10, 4))  # Should output 4

# Let's also verify with a more detailed explanation
def get_total_number_of_sequences_v2(m, n):
    # Using dynamic programming with memoization
    memo = {}

    def count_sequences(remaining_length, last_value):
        # Base case: if no more elements needed, we found one valid sequence
        if remaining_length == 0:
            return 1

        # If we've already computed this state, return it
        if (remaining_length, last_value) in memo:
            return memo[(remaining_length, last_value)]

        total = 0
        # Try all possible values for the next element
        for current_value in range(last_value, m + 1):
            # Check if current_value >= 2 * last_value
            if current_value >= 2 * last_value:
                total += count_sequences(remaining_length - 1, current_value)

        memo[(remaining_length, last_value)] = total
        return total

    # Start with all possible first elements
    result = 0
    for first_element in range(1, m + 1):
        result += count_sequences(n - 1, first_element)

    return result

# Test both versions
print("Version 1:", get_total_number_of_sequences(10, 4))
print("Version 2:", get_total_number_of_sequences_v2(10, 4))

