def trace_small_example():
    print("\nTracing small example (m=5, n=3):")
    print("Valid sequences:")
    sequences = []

    def backtrack(current_seq, last_val):
        if len(current_seq) == 3:
            sequences.append(current_seq[:])
            return

        for val in range(last_val, 6):  # val >= last_val and val <= 5
            if not current_seq or val >= 2 * last_val:
                current_seq.append(val)
                backtrack(current_seq, val)
                current_seq.pop()

    backtrack([], 0)
    for seq in sequences:
        print(seq)

