def find_kth(arr1, arr2, k):
    # If first array is empty, return kth element from second array
    if len(arr1) == 0:
        return arr2[k-1]

    # If second array is empty, return kth element from first array
    if len(arr2) == 0:
        return arr1[k-1]

    # If k is 1, return minimum of first elements of both arrays
    if k == 1:
        return min(arr1[0], arr2[0])

    # Calculate midpoints for both arrays
    mid1 = min(len(arr1), k//2)
    mid2 = min(len(arr2), k//2)

    # Compare elements at midpoints and eliminate half of one array
    if arr1[mid1-1] < arr2[mid2-1]:
        # Eliminate first mid1 elements from arr1
        return find_kth(arr1[mid1:], arr2, k-mid1)
    else:
        # Eliminate first mid2 elements from arr2
        return find_kth(arr1, arr2[mid2:], k-mid2)

