def dict_depth_generator(d):
    def get_depths(obj, level=0):
        if isinstance(obj, dict):
            yield level
            for value in obj.values():
                yield from get_depths(value, level + 1)
        else:
            yield level

    if not isinstance(d, dict) or not d:
        return 0

    return max(get_depths(d))

