import heapq

def large_product(list1, list2, n):
    # Create a max heap using negative values
    heap = []

    # Generate all possible products and add them to the heap
    for num1 in list1:
        for num2 in list2:
            product = num1 * num2
            heapq.heappush(heap, -product)  # Use negative for max heap behavior

    # Extract the n largest products
    result = []
    for _ in range(n):
        if heap:
            result.append(-heapq.heappop(heap))  # Convert back to positive
        else:
            break

    return result

