def max_aggregate(tuple_list):
    # Create a dictionary to store the sum of scores for each name
    aggregate_scores = {}

    # Iterate through the list of tuples
    for name, score in tuple_list:
        if name in aggregate_scores:
            aggregate_scores[name] += score
        else:
            aggregate_scores[name] = score

    # Find the name with the maximum aggregate score
