from collections import defaultdict


def largest_subset(nums):
    """
    :type nums: List[int]
    :rtype: int
    """
    if not nums:
        return 0

    # sort the array first
    nums.sort()
    # dp[i] means the largest subset ending with nums[i]
    dp = [1] * len(nums)
    # divisors[i] stores all divisors of nums[i]
    divisors = defaultdict(list)

    for i in range(len(nums)):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                divisors[i].append(j)

    for i in range(1, len(nums)):
        for divisor in divisors[i]:
            dp[i] = max(dp[i], dp[divisor] + 1)

    return max(dp)


