def newton_raphson(x_guess, tolerance=1e-7, max_iterations=1000):
    for _ in range(max_iterations):
        fx = poly(coeffs, x_guess)
        if abs(fx) < tolerance:
            return x_guess
        dfx = poly(derivative(coeffs), x_guess)
        if abs(dfx) < tolerance:
            break
        x_guess = x_guess - fx / dfx
    return x_guess

