def dict_depth(d):
    if not isinstance(d, dict) or not d:
        return 0
    return 1 + max(dict_depth(v) for v in d.values())

print(dict_depth({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative approach using stack
def dict_depth_stack(d):
    if not isinstance(d, dict) or not d:
        return 0

    stack = [d]
    depth = 0

    while stack:
        current = stack.pop()
        if isinstance(current, dict):
            depth += 1
            stack.extend(current.values())

    return depth

print(dict_depth_stack({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative approach using recursion with level tracking
def dict_depth_recursive(d, level=1):
    if not isinstance(d, dict) or not d:
        return level - 1

    max_depth = level
    for value in d.values():
        if isinstance(value, dict):
            current_depth = dict_depth_recursive(value, level + 1)
            max_depth = max(max_depth, current_depth)

    return max_depth

print(dict_depth_recursive({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative approach using collections.deque for BFS-like traversal
from collections import deque

def dict_depth_bfs(d):
    if not isinstance(d, dict) or not d:
        return 0

    queue = deque([(d, 1)])
    max_depth = 1

    while queue:
        current_dict, current_level = queue.popleft()
        max_depth = max(max_depth, current_level)

        for value in current_dict.values():
            if isinstance(value, dict):
                queue.append((value, current_level + 1))

    return max_depth

print(dict_depth_bfs({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative approach using a helper function with memoization
def dict_depth_memo(d, memo=None):
    if memo is None:
        memo = {}

    if id(d) in memo:
        return memo[id(d)]

    if not isinstance(d, dict) or not d:
        memo[id(d)] = 0
        return 0

    result = 1 + max(dict_depth_memo(v, memo) for v in d.values())
    memo[id(d)] = result
    return result

print(dict_depth_memo({'a':1, 'b': {'c': {'d': {}}}})) # 4

