from collections import defaultdict

def largest_subset(nums):
    # Create a graph where an edge from a to b means b is divisible by a
    graph = defaultdict(list)
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[j] % nums[i] == 0:
                graph[nums[i]].append(nums[j])
            elif nums[i] % nums[j] == 0:
                graph[nums[j]].append(nums[i])

    # Find longest path in DAG using topological sort and dynamic programming
    # Calculate in-degrees
    indegree = defaultdict(int)
    for node in graph:
        for neighbor in graph[node]:
            indegree[neighbor] += 1

    # Initialize dp with 1 (each node forms a subset of size 1)
    dp = {node: 1 for node in graph}

    # Topological sort using Kahn's algorithm
    queue = [node for node in graph if indegree[node] == 0]

    while queue:
        current = queue.pop(0)
        for neighbor in graph[current]:
            # Update the longest path ending at neighbor
            dp[neighbor] = max(dp[neighbor], dp[current] + 1)
            # Reduce in-degree
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return max(dp.values()) if dp else 1


