    def newton_raphson(x0, tolerance=1e-7, max_iterations=1000):
        x = x0
        for _ in range(max_iterations):
            fx = poly(coeffs, x)
            if abs(fx) < tolerance:
                return x
            dfx = poly(derivative(coeffs), x)
            if abs(dfx) < tolerance:
                break
            x = x - fx / dfx
        return x

    # Try different starting points
    start_points = [0, 1, -1, 0.5, -0.5]
    coeffs = xs[:]
    for x0 in start_points:
        try:
            root = newton_raphson(x0)
            if abs(poly(coeffs, root)) < 1e-6:
                return root
        except:
            continue

    raise ValueError("Could not find a root using Newton-Raphson method")

