        # Move right pointer to previous vowel
        while left < right and s_list[right] not in vowels:
            right -= 1

        # Swap vowels
        if left < right:
            s_list[left], s_list[right] = s_list[right], s_list[left]
            left += 1
            right -= 1

    return ''.join(s_list)

