    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5)+1, 2):
            if n % i == 0:
                return False
        return True

    # Check if a is less than 2 or greater than 99
    if a < 2 or a > 99:
        return False

    # Find all prime factors of a
    prime_factors = []
    for i in range(2, int(a**0.5)+1):
        if a % i == 0:
            if is_prime(i):
                prime_factors.append(i)
            if is_prime(a // i) and a // i != i:
                prime_factors.append(a // i)

    # If there are exactly 3 prime factors, return True
    return len(prime_factors) == 3

