print(is_samepatterns(["red","green","blue"], ["a", "b", "b"]))  # False
print(is_samepatterns([], []))  # True
print(is_samepatterns(["red"], ["a"]))  # True
print(is_samepatterns(["red","green"], ["a", "a"]))  # False
print(is_samepatterns(["red","red"], ["a", "b"]))  # False

