def dict_depth_iterative(d):
    if not isinstance(d, dict) or not d:
        return 0

    queue = [d]
    depth = 0

    while queue:
        depth += 1
        size = len(queue)

        for _ in range(size):
            current = queue.pop(0)
            if isinstance(current, dict):
                queue.extend(current.values())

    return depth

